from django.http import JsonResponse
from django.contrib.auth.decorators import login_required
from django.views.decorators.cache import cache_page
from django.views.decorators.vary import vary_on_cookie
from .models import DeveloperAccount

@login_required
@vary_on_cookie
@cache_page(120)
def developer_api_quota_view(request):
    account = DeveloperAccount.objects.get(owner=request.user)
    return JsonResponse({
        'app_name': account.application_name,
        'api_key_prefix': account.key_prefix,
        'monthly_quota': account.quota_limit,
        'requests_consumed': account.requests_consumed
    })
